-- Lane A figures for None: generated by build_load_sql.py, do not hand-edit.
-- 2 figures across 1 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: none
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('arrow_diagram', 'Vector and free-body arrows', 'Arrows from a common origin, each at a stated angle with its length proportional to its magnitude on ONE scale shared by every arrow in the figure. Carries an optional chosen coordinate axis, and a perpendicular offset so two forces in the same direction are drawn side by side rather than one on top of the other. The first Lane B grammar: it asserts a drawing convention rather than a quantity on an axis, so it renders in the bare frame.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys-vector-arrows', 'ap_physics_1', 'arrow_diagram', 'Drawing a vector as an arrow', 'Arrow = direction + length', 'Direction is where it points; length is proportional to magnitude', 'Three velocities drawn from one point on a single scale: 6.0 m/s east, 3.0 m/s north and 4.5 m/s south-west. The 3.0 arrow is exactly half the length of the 6.0 arrow because the scale is the same for all three.', 'Three velocity vectors drawn as arrows from a single common point. One points right, labelled 6.0 metres per second; one points straight up, labelled 3.0 metres per second; one points down and to the left, labelled 4.5 metres per second. Each arrow points in the direction of its velocity, and the arrows are drawn to one scale, so the 3.0 arrow is exactly half the length of the 6.0 arrow and the 4.5 arrow is three quarters of it. Length carries the magnitude and nothing else: a longer arrow is a larger velocity, not a different kind of quantity. Illustrative data.', '', '', 'One scale for all three: half the magnitude is half the length.', true, null, '["Arrow direction", "Arrow length"]'::jsonb, '{"dot": true, "unit_note": "drawn to one scale: 6.0 m/s is the longest arrow", "arrows": [{"label": "6.0 m/s", "magnitude": 6.0, "angle_deg": 0}, {"label": "3.0 m/s", "magnitude": 3.0, "angle_deg": 90}, {"label": "4.5 m/s", "magnitude": 4.5, "angle_deg": 215}], "proportionality_check": true}'::jsonb, null, null, 'published', 'cramapple-authored; batch=phys-vector,phys-free-figures-2026-10-11', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('phys-free-body-diagram', 'ap_physics_1', 'arrow_diagram', 'Free-body diagram of a block on an incline', 'Free-body diagram', 'Every force on the block, drawn whole, acting at one dot', 'A block held at rest on a 30 degree incline by a rope. Four forces act on it: its weight, the normal force from the surface, the rope''s 2.0 N pull up the slope and 3.0 N of friction up the slope. The dashed line is the chosen axis, parallel to the incline.', 'A free-body diagram for a block at rest on a thirty-degree incline. A single dot stands for the block, and every force the environment exerts on it acts at that dot. The weight, 10.0 newtons, points straight down and is the longest arrow. The normal force, 8.7 newtons, points away from the surface at right angles to it. The rope''s pull, 2.0 newtons, and friction, 3.0 newtons, both point up the slope, so they are drawn just to either side of the dot rather than one on top of the other; that sideways shift is a drawing convention to keep both readable and does not mean they act anywhere else. A dashed line through the dot marks the chosen axis, parallel to the incline. Only whole forces are drawn: the weight appears once, and its components along and across the slope are not drawn beside it. The four forces add to zero, which is why the block stays at rest. Illustrative data.', '', '', 'The four add to zero, which is what holding the block at rest means.', true, null, '["Dot", "Force arrows", "Same-direction forces", "Whole forces only", "Coordinate axis"]'::jsonb, '{"dot": true, "axis": {"angle_deg": 30.0, "label": "incline axis"}, "unit_note": "forces in newtons; same-direction forces are drawn side by side", "arrows": [{"label": "weight 10.0 N", "magnitude": 10.0, "angle_deg": 270}, {"label": "normal 8.7 N", "magnitude": 8.660254, "angle_deg": 120.0}, {"label": "rope 2.0 N", "magnitude": 2.0, "angle_deg": 30.0, "offset": 0.85}, {"label": "friction 3.0 N", "magnitude": 3.0, "angle_deg": 30.0, "offset": -0.85}], "proportionality_check": true, "equilibrium_check": true, "whole_forces_check": true}'::jsonb, null, null, 'published', 'cramapple-authored; batch=phys-vector,phys-free-figures-2026-10-11', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys-vector-arrows', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_1' and e.kind = 'diagram'
   and e.title = 'Vector arrow representation' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys-vector-arrows', e.reference_entry_id, 'secondary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_c_mechanics' and e.kind = 'diagram'
   and e.title = 'Vector arrow representation' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys-free-body-diagram', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_1' and e.kind = 'diagram'
   and e.title = 'Free-body diagram (FBD)' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'phys-free-body-diagram', e.reference_entry_id, 'secondary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_physics_c_mechanics' and e.kind = 'diagram'
   and e.title = 'Free-body diagram' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('phys-vector-arrows', 'phys-free-body-diagram') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('phys-vector-arrows', 'phys-free-body-diagram');
  if v_n <> 2 then
    raise exception 'expected 2 figures, found %', v_n;
  end if;
end $$;

commit;
